        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            var descEl = document.getElementById('briefingText');

            if (window.mySimulation && window.mySimulation.t) {
                if (titleEl) titleEl.textContent = window.mySimulation.t(round.titleKey);
                if (descEl) descEl.textContent = window.mySimulation.t(round.descKey);
            }
        }

        _updateAllocTotal() {
            var total = 0;
            var ids = ['cleanEnergyInput', 'healthTechInput', 'edTechInput', 'agriTechInput'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el) total += parseInt(el.value) || 0;
            }
            var display = document.getElementById('totalAllocDisplay');
            if (display) {
                display.textContent = total + '%';
                display.style.color = total === 100 ? '#27ae60' : '#e74c3c';
            }
        }

        _updateStrategyDisplay() {
            var el = document.getElementById('strategyInput');
            var display = document.getElementById('strategyDisplay');
            if (el && display) {
                var val = parseInt(el.value);
                var labelKey = val <= 3 ? 'finance_first' : val <= 7 ? 'balanced' : 'impact_first';
                var label = window.mySimulation && window.mySimulation.t ? window.mySimulation.t(labelKey) : '';
                display.textContent = val + ' - ' + label;
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ImpactInvestAdapter(), {
            simulationType: 'impact_investing_portfolio',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

})();
